val username: String? = null

// Safe call operator (?.)
val length: Int? = username?.length

// Elvis operator (?:) para proveer un fallback seguro
val displayName: String = username ?: "Invitado"

println("Hola, $displayName!")

fun calculateDiscount(originalPrice: Double, discountPercentage: Double): Double {
    require(discountPercentage in 0.0..100.0) { "Porcentaje inválido" }
    return originalPrice * (1.0 - discountPercentage / 100.0)
}

val finalPrice = calculateDiscount(originalPrice = 80.0, discountPercentage = 25.0)
println("Precio final: $finalPrice")
